35	// Only the requester's own session is rejoined; a miss, a store failure and a not-yours all read as no resume.
36	export async function resumableSession(
37	  store: SessionStore,
38	  requester: Requester,
39	  options?: SessionResumeOptions
40	): Promise<ResumeOutcome> {
