110	  if ('suppressed' in entry && entry.suppressed) {
111	    sendSkip(ws, index);
112	    return;
113	  }
114	  // Its turn streams to the socket that started it, so this client is shown it cut off rather than waiting on it.
115	  if ('isStreaming' in entry && entry.isStreaming) {
116	    sendUpsert(ws, index, {...entry, isStreaming: false, truncated: true});
117	    return;
118	  }
119	  sendUpsert(ws, index, entry);
120	}
