      ['seed-b', 'u1', sentAt(3)],
      ['seed-c', 'u1', sentAt(2)],
      ['mallory-seed', 'mallory', sentAt(1)],
    ]);
    const gate = deferred();
    const {base} = await startEngine(store, {
      history: {enabled: true},
      resume: {enabled: true},
