      listCalls: [{userId: 'u1', options: {limit: 2, before: {updatedAt: CURSOR_AT_A, sessionId: 'seed-a'}}}],
      // The page resumes after the row the cursor names, so the answer is the two older conversations.
      ids: ['seed-b', 'seed-c'],
      isoTimes: true,
