import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {HalServerOptions} from './createServer.js';
import type {SessionResumeOptions} from './ws/sessionResume.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';
import {answeringOrchestrator, deferred} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// A conversation list delivered over the WebSocket itself, so no consumer has to stand up a second,
// authenticated HTTP route over the same personal data the engine authenticated on the upgrade.

interface Row {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

interface Frame {
  type: string;
  sessionId?: string;
  resumed?: boolean;
  code?: string;
  message?: string;
  conversations?: Row[];
}

// Typed beside HalServerOptions rather than inside it, so the file compiles before the option is named and after.
type ServerOptions = HalServerOptions & {history?: {enabled: boolean}};

const SILENT = {debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined};
const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];

// Entry stamps are fixed far ahead of any run date, so the newest-first order never depends on the clock.
const sentAt = (second: number): string => `2031-01-01T00:00:0${second}.000Z`;
const CURSOR_AT_A = '2031-01-01T00:00:04.000Z';

const seed = (store: InMemorySessionStore, conversations: Array<[id: string, owner: string, at: string]>): void => {
  for (const [sessionId, userId, timestamp] of conversations) {
    const {entries} = store.create(sessionId, userId);
    entries.push({role: 'user', content: sessionId, timestamp});
  }
};

const storeWith = (conversations: Array<[id: string, owner: string, at: string]>): InMemorySessionStore => {
  const store = new InMemorySessionStore();
  seed(store, conversations);
  return store;
};

// Records what the transport asked the store for, which is where the authorisation assertion lives.
class RecordingListStore extends InMemorySessionStore {
  readonly calls: Array<{userId: string | number; options: {limit?: number; before?: unknown}}> = [];
  override listFor(userId: string | number, options?: SessionListOptions): SessionSummary[] {
    this.calls.push({userId, options: {limit: options?.limit, before: options?.before}});
    return super.listFor(userId, options);
  }
}

// A store written against the five original members, with no listFor to answer a history frame with.
const withoutList = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

// A database that failed mid-read, whose own detail must never reach the client's frame.
const withFailingList = (inner: InMemorySessionStore): SessionStore => ({
  ...withoutList(inner),
  listFor: async () => {
    throw new Error('replica set rs/eu-west-1 unreachable');
  },
});

const parkedAnswer = (gate: {until: Promise<void>}): ChatOrchestrator => ({
  processMessage: async () => 'hi',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'first '};
    await gate.until;
    yield {type: 'text', text: 'second'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
});

const startEngine = async (
  sessionStore: SessionStore,
  extra: {history?: {enabled: boolean}; resume?: SessionResumeOptions; orchestrator?: ChatOrchestrator} = {}
): Promise<string> => {
  const options: ServerOptions = {
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    sessionStore,
    orchestrator: extra.orchestrator ?? answeringOrchestrator,
    resume: extra.resume,
    history: extra.history,
  };
  const hal = createServer(options);
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const connect = (
  url: string
): {client: WebSocket; frames: Frame[]; send: (frame: unknown) => void; until: (type: string) => Promise<void>} => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  client.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  return {
    client,
    frames,
    send: frame => client.send(JSON.stringify(frame)),
    // Capped well under jest's own five second timeout, so a red test reports its diff instead of dying.
    until: async type => {
      for (let attempt = 0; attempt < 250 && !frames.some(frame => frame.type === type); attempt++) {
        await new Promise(resolve => setTimeout(resolve, 10));
      }
    },
  };
};

const list = (fields: Record<string, unknown> = {}): Record<string, unknown> => ({
  type: 'list_conversations',
  ...fields,
});
const typesOf = (frames: Frame[]): string[] => frames.map(frame => frame.type);
const frameOf = (frames: Frame[], type: string): Frame | undefined => frames.find(frame => frame.type === type);
const iso = (value: string): boolean => Number.isFinite(Date.parse(value));

beforeAll(() => {
  setLogger(SILENT);
});

afterAll(() => {
  setLogger();
});

// Each server sees its sockets close before it stops, so no close is logged after the logger is restored.
afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    for (let attempt = 0; attempt < 50 && wss.clients.size > 0; attempt++) {
      await new Promise(resolve => setTimeout(resolve, 10));
    }
    await hal.stop();
  }
});

describe('a conversation list delivered over the websocket', () => {
  it('accepts list_conversations and refuses a limit or a cursor it cannot use, naming the field', () => {
    const verdictOf = (frame: unknown): string => {
      const result = validateMessage(frame);
      if (!result.valid) {
        return /limit/.test(result.error)
          ? 'invalid: limit'
          : /before/.test(result.error)
            ? 'invalid: before'
            : 'invalid: other';
      }
      return 'valid';
    };

    expect({
      bare: verdictOf({type: 'list_conversations'}),
      // There is no user id field on the frame, so an extra one is an ignored field, not a validation failure.
      carryingAnotherUsersId: verdictOf({type: 'list_conversations', userId: 'mallory'}),
      smallestLimit: verdictOf({type: 'list_conversations', limit: 1}),
      largestLimit: verdictOf({type: 'list_conversations', limit: 200}),
      wholeCursor: verdictOf({type: 'list_conversations', before: {updatedAt: CURSOR_AT_A, sessionId: 's1'}}),
      zeroLimit: verdictOf({type: 'list_conversations', limit: 0}),
      overLargeLimit: verdictOf({type: 'list_conversations', limit: 201}),
      fractionalLimit: verdictOf({type: 'list_conversations', limit: 1.5}),
      stringLimit: verdictOf({type: 'list_conversations', limit: '10'}),
      unusableBefore: verdictOf({type: 'list_conversations', before: 'not a date'}),
      epochBefore: verdictOf({type: 'list_conversations', before: {updatedAt: 1767225604000, sessionId: 's1'}}),
      cursorWithoutId: verdictOf({type: 'list_conversations', before: {updatedAt: CURSOR_AT_A}}),
      cursorWithoutTime: verdictOf({type: 'list_conversations', before: {sessionId: 's1'}}),
    }).toEqual({
      bare: 'valid',
      carryingAnotherUsersId: 'valid',
      smallestLimit: 'valid',
      largestLimit: 'valid',
      wholeCursor: 'valid',
      zeroLimit: 'invalid: limit',
      overLargeLimit: 'invalid: limit',
      fractionalLimit: 'invalid: limit',
      stringLimit: 'invalid: limit',
      unusableBefore: 'invalid: before',
      epochBefore: 'invalid: before',
      cursorWithoutId: 'invalid: before',
      cursorWithoutTime: 'invalid: before',
    });
  });

  it('answers a history request off the turn with the conversations of the connecting user, and a row of it rejoins through resume', async () => {
    const store = new RecordingListStore();
    seed(store, [
      ['seed-a', 'u1', sentAt(4)],
      ['seed-b', 'u1', sentAt(3)],
      ['seed-c', 'u1', sentAt(2)],
      ['mallory-seed', 'mallory', sentAt(1)],
    ]);
    const gate = deferred();
    const base = await startEngine(store, {
      history: {enabled: true},
      resume: {enabled: true},
      orchestrator: parkedAnswer(gate),
    });

    const first = connect(base);
    await first.until('connected');
    const ownId = frameOf(first.frames, 'connected')?.sessionId ?? '';

    // The list is asked for while a turn is parked mid-answer: it must not queue behind that turn.
    first.send({type: 'user_message', content: 'hello'});
    await first.until('entry_delta');
    first.send(list({userId: 'mallory'}));
    await first.until('conversation_list');
    gate.release();
    await first.until('stream_end');

    const rows = frameOf(first.frames, 'conversation_list')?.conversations ?? [];
    const rowId = rows[0]?.sessionId ?? 'no row answered';

    const second = connect(`${base}?sessionId=${rowId}`);
    await second.until('entry_upsert');

    expect({
      exchange: typesOf(first.frames),
      rows: rows.map(row => ({id: row.sessionId, entries: row.entryCount, keys: Object.keys(row).sort()})),
      isoTimes: rows.every(row => iso(row.createdAt) && iso(row.updatedAt)),
      listCalls: store.calls,
      resumed: frameOf(second.frames, 'connected')?.resumed,
      replay: typesOf(second.frames),
    }).toEqual({
      // The list is answered inside the parked turn, before its stream_end, and is not a turn of its own.
      exchange: [
        'connected',
        'entry_upsert',
        'entry_upsert',
        'entry_delta',
        'conversation_list',
        'entry_delta',
        'entry_commit',
        'stream_end',
      ],
      rows: [
        {id: 'seed-a', entries: 1, keys: ['createdAt', 'entryCount', 'sessionId', 'updatedAt']},
        {id: 'seed-b', entries: 1, keys: ['createdAt', 'entryCount', 'sessionId', 'updatedAt']},
        {id: 'seed-c', entries: 1, keys: ['createdAt', 'entryCount', 'sessionId', 'updatedAt']},
        // The conversation the connection is in is listed like any other, holding no entries yet.
        {id: ownId, entries: 0, keys: ['createdAt', 'entryCount', 'sessionId', 'updatedAt']},
      ],
      isoTimes: true,
      // Asked for with another user's id on the frame, answered from the connection's own.
      listCalls: [{userId: 'u1', options: {limit: undefined, before: undefined}}],
      resumed: true,
      replay: ['connected', 'entry_upsert'],
    });
  }, 15000);

  it('passes limit and before to the store as the frame sent them, and warns when history is on without resume', async () => {
    const store = new RecordingListStore();
    seed(store, [
      ['seed-a', 'u1', sentAt(4)],
      ['seed-b', 'u1', sentAt(3)],
      ['seed-c', 'u1', sentAt(2)],
      ['mallory-seed', 'mallory', sentAt(1)],
    ]);
    const warnings: string[] = [];
    setLogger({...SILENT, warn: (_category, message, fields) => warnings.push(JSON.stringify([message, fields]))});
    let rows: Row[] = [];
    let connectedKeys: string[] = [];
    try {
      const base = await startEngine(store, {history: {enabled: true}});
      const first = connect(base);
      await first.until('connected');
      first.send(list({limit: 2, before: {updatedAt: CURSOR_AT_A, sessionId: 'seed-a'}}));
      await first.until('conversation_list');
      rows = frameOf(first.frames, 'conversation_list')?.conversations ?? [];
      connectedKeys = Object.keys(frameOf(first.frames, 'connected') ?? {}).sort();
    } finally {
      setLogger(SILENT);
    }

    expect({
      connectedKeys,
      listCalls: store.calls,
      ids: rows.map(row => row.sessionId),
      isoTimes: rows.every(row => iso(row.createdAt) && iso(row.updatedAt)),
      warnedAboutHistoryWithoutResume: warnings.some(line => /history/.test(line) && /resume/.test(line)),
    }).toEqual({
      connectedKeys: ['examplePrompts', 'message', 'sessionId', 'type'],
      listCalls: [{userId: 'u1', options: {limit: 2, before: {updatedAt: CURSOR_AT_A, sessionId: 'seed-a'}}}],
      // The page resumes after the row the cursor names, so the answer is the two older conversations.
      ids: ['seed-b', 'seed-c'],
      isoTimes: true,
      warnedAboutHistoryWithoutResume: true,
    });
  });

  it('answers a list it cannot offer with an UNSUPPORTED error, never an empty list', async () => {
    const held = storeWith([['seed-a', 'u1', sentAt(1)]]);

    const disabled = connect(await startEngine(storeWith([['seed-a', 'u1', sentAt(1)]])));
    await disabled.until('connected');
    disabled.send(list());
    await disabled.until('error');

    const noList = connect(await startEngine(withoutList(held), {history: {enabled: true}}));
    await noList.until('connected');
    noList.send(list());
    await noList.until('error');

    expect({
      disabledFrames: typesOf(disabled.frames),
      disabledCode: frameOf(disabled.frames, 'error')?.code,
      unlistedFrames: typesOf(noList.frames),
      unlistedCode: frameOf(noList.frames, 'error')?.code,
    }).toEqual({
      disabledFrames: ['connected', 'error'],
      disabledCode: 'UNSUPPORTED',
      unlistedFrames: ['connected', 'error'],
      // A user who has conversations is told of a failure, never shown a history they do not have.
      unlistedCode: 'UNSUPPORTED',
    });
  });

  it('answers a store that fails to list with SERVER_ERROR and no store detail, and keeps the socket open', async () => {
    const base = await startEngine(withFailingList(storeWith([['seed-a', 'u1', sentAt(1)]])), {
      history: {enabled: true},
    });
    const first = connect(base);
    await first.until('connected');
    const ownId = frameOf(first.frames, 'connected')?.sessionId ?? '';

    const errors: Array<Record<string, unknown>> = [];
    setLogger({...SILENT, error: (category, message, fields) => errors.push({category, message, ...fields})});
    try {
      first.send(list());
      await first.until('error');
      // The socket took an error frame and stayed answering: a failed list is not a dropped connection.
      first.send({type: 'ping', timestamp: 7});
      await first.until('pong');
    } finally {
      setLogger(SILENT);
    }

    const logged = JSON.stringify(errors);
    expect({
      exchange: typesOf(first.frames),
      code: frameOf(first.frames, 'error')?.code,
      storeDetailLogged: logged.includes('rs/eu-west-1'),
      userContentLogged: logged.includes('seed-a'),
      sessionIdLogged: logged.includes(ownId),
    }).toEqual({
      exchange: ['connected', 'error', 'pong'],
      code: 'SERVER_ERROR',
      storeDetailLogged: false,
      userContentLogged: false,
      sessionIdLogged: true,
    });
  });

  it('answers a store throwing StoreCannotList with UNSUPPORTED, not a server error', async () => {
    // Read reflectively so this file compiles before the class is exported: a red guard names what is missing.
    const exported = (await import('../types/sessionStore.js')) as unknown as Record<string, unknown>;
    const StoreCannotList = exported['StoreCannotList'] as (new (message?: string) => Error) | undefined;
