    };
    const base = await startEngine(cannotList, {history: {enabled: true}});

    const first = connect(base);
    await first.until('connected');
    first.send(list());
    await first.until('error');

    expect({
      exchange: typesOf(first.frames),
      code: frameOf(first.frames, 'error')?.code,
    }).toEqual({
